require "openssl"

# Verifies a file signed outside the app: CAdES (.p7m, attached or detached) or PAdES (signed PDF).
#
# Checks: the signature is intact, the signer certificate was valid when signing, it is meant for
# signing documents (non-repudiation) and is qualified (QcCompliance + QSCD), and the signed content
# is exactly the PDF generated by the app.
#
# The issuer chain against the EU trusted list is not checked yet: a signature that passes every
# other check comes out as :valid_untrusted.
class SignatureVerifier
  Result = Data.define(:status, :format, :signer_name, :signer_tax_code, :issuer, :certificate_serial,
                       :certificate_valid_until, :signed_at, :timestamped, :qualified, :matches_original, :details)

  OID_QC_COMPLIANCE = "0.4.0.1862.1.1"
  OID_QC_SSCD = "0.4.0.1862.1.4"
  OID_SIGNATURE_TIMESTAMP = "1.2.840.113549.1.9.16.2.14" # id-aa-signatureTimeStampToken (CAdES-T)
  TAX_CODE = /[A-Z]{6}\d{2}[A-Z]\d{2}[A-Z]\d{3}[A-Z]/
  BYTE_RANGE = %r{/ByteRange\s*\[\s*(\d+)\s+(\d+)\s+(\d+)\s+(\d+)\s*\]}
  NO_CHAIN = OpenSSL::PKCS7::NOVERIFY | OpenSSL::PKCS7::BINARY

  class Unreadable < StandardError; end

  # signed: bytes of the uploaded file; original: bytes of the PDF generated by the app, if any
  def initialize(signed, original: nil)
    @signed = signed.b
    @original = original&.b
    @errors = []
    @warnings = []
    @checks = {}
  end

  def call
    pdf? ? verify_pades : verify_cades
  rescue Unreadable, OpenSSL::PKCS7::PKCS7Error, OpenSSL::ASN1::ASN1Error, ArgumentError => e
    Rails.logger.info("[SignatureVerifier] unreadable file: #{e.class}: #{e.message}")
    @errors << "unreadable"
    result(format: nil, cert: nil, signed_at: nil, timestamped: false, matches_original: nil)
  end

  private

  def pdf?
    @signed.start_with?("%PDF")
  end

  # --- CAdES (.p7m) -------------------------------------------------------------------------

  def verify_cades
    der = cades_der
    p7 = OpenSSL::PKCS7.new(der)
    detached = p7.detached? # p7.data of a parsed file is only filled in by #verify
    raise Unreadable, "detached signature without the original PDF" if detached && @original.nil?

    @checks[:integrity] = p7.verify([], OpenSSL::X509::Store.new, detached ? @original : nil, NO_CHAIN)
    matches = detached ? @checks[:integrity] : (@original && p7.data.to_s.b == @original)

    result(format: "cades", cert: signer_certificate(p7), signed_at: signing_time(p7),
           timestamped: oids_in(der).include?(OID_SIGNATURE_TIMESTAMP), matches_original: matches)
  end

  # .p7m files come as DER or, from some tools, Base64 (with or without PEM armour)
  def cades_der
    return @signed if @signed.getbyte(0) == 0x30

    body = @signed.gsub(/-----[A-Z0-9 ]+-----/, "").gsub(/\s/, "")
    raise Unreadable, "not a PKCS#7 file" unless body.match?(/\A[A-Za-z0-9+\/]+=*\z/)

    body.unpack1("m0")
  end

  # --- PAdES (signed PDF) -------------------------------------------------------------------

  def verify_pades
    entries = pdf_signatures
    raise Unreadable, "PDF without digital signatures" if entries.empty?

    timestamps, signatures = entries.partition { |e| e[:sub_filter] == "ETSI.RFC3161" }
    raise Unreadable, "PDF with only document timestamps" if signatures.empty?

    # The last signature covers the version that was signed; later updates may only add
    # document timestamps (PAdES-LTA). Anything else changed the file after signing.
    signature = signatures.max_by { |e| e[:end] }
    last_end = entries.map { |e| e[:end] }.max
    @checks[:covers_whole_file] = last_end == @signed.bytesize && timestamps.all? { |t| t[:end] >= signature[:end] }
    @errors << "modified_after_signature" unless @checks[:covers_whole_file]

    p7 = OpenSSL::PKCS7.new(signature[:der])
    @checks[:integrity] = p7.verify([], OpenSSL::X509::Store.new, signature[:signed_data], NO_CHAIN)

    # Signing tools add the signature as an incremental update: the signed file starts with the original bytes
    matches = @original && @signed.byteslice(0, @original.bytesize) == @original

    result(format: "pades", cert: signer_certificate(p7), signed_at: signing_time(p7) || signature[:m_date],
           timestamped: timestamps.any? || oids_in(signature[:der]).include?(OID_SIGNATURE_TIMESTAMP),
           matches_original: matches)
  end

  def pdf_signatures
    @signed.to_enum(:scan, BYTE_RANGE).map do
      a, b, c, d = Regexp.last_match.captures.map(&:to_i)
      next unless a.zero? && c > b && c + d <= @signed.bytesize

      contents = @signed.byteslice(b, c - b).delete("<> \r\n")
      next unless contents.match?(/\A\h+\z/)

      # the signature dictionary around /Contents: from its "N 0 obj" to "endobj"
      dict_start = @signed.rindex(/\d+\s+\d+\s+obj\b/, b) || [ b - 4096, 0 ].max
      dict_end = @signed.index("endobj", c) || [ c + 4096, @signed.bytesize ].min
      dictionary = @signed.byteslice(dict_start, b - dict_start) + @signed.byteslice(c, dict_end - c)
      {
        der: [ contents.sub(/(00)+\z/, "") ].pack("H*"),
        signed_data: @signed.byteslice(a, b) + @signed.byteslice(c, d),
        end: c + d,
        sub_filter: dictionary.scan(%r{/SubFilter\s*/([\w.]+)}).flatten.last,
        m_date: pdf_date(dictionary[%r{/M\s*\((D:[^)]+)\)}, 1])
      }
    end.compact
  end

  # PDF dates: D:YYYYMMDDHHmmSS+HH'mm'
  def pdf_date(value)
    m = value&.match(/D:(\d{4})(\d{2})(\d{2})(\d{2})(\d{2})(\d{2})?(?:([+-])(\d{2})'?(\d{2})?)?/)
    return unless m

    offset = m[7] ? "#{m[7]}#{m[8]}:#{m[9] || '00'}" : "+00:00"
    Time.new(m[1].to_i, m[2].to_i, m[3].to_i, m[4].to_i, m[5].to_i, m[6].to_i, offset)
  rescue ArgumentError
    nil
  end

  # --- certificate ------------------------------------------------------------------------

  def signer_certificate(p7)
    info = p7.signers.first or raise Unreadable, "no signer"
    p7.certificates.to_a.find { |c| c.serial == info.serial && c.issuer.cmp(info.issuer).zero? } or
      raise Unreadable, "signer certificate not included"
  end

  def signing_time(p7)
    p7.signers.first&.signed_time
  end

  def check_certificate(cert, signed_at)
    at = signed_at || Time.current
    @checks[:certificate_valid_at_signing] = cert.not_before <= at && at <= cert.not_after
    @errors << "certificate_not_valid_at_signing" unless @checks[:certificate_valid_at_signing]

    key_usage = cert.extensions.find { |e| e.oid == "keyUsage" }&.value.to_s
    @checks[:non_repudiation] = key_usage.match?(/Non Repudiation|Content Commitment/)
    @warnings << "no_non_repudiation" unless @checks[:non_repudiation]

    qc = cert.extensions.find { |e| e.oid.in?([ "qcStatements", "1.3.6.1.5.5.7.1.3" ]) }
    qc_oids = qc ? oids_in(qc.value_der) : []
    @checks[:qualified] = qc_oids.include?(OID_QC_COMPLIANCE)
    @checks[:qscd] = qc_oids.include?(OID_QC_SSCD)
    @warnings << "not_qualified" unless @checks[:qualified] && @checks[:qscd]
  end

  def subject_fields(name)
    name.to_a.each_with_object({}) { |(key, value, _), h| h[key] = value.force_encoding(Encoding::UTF_8) }
  end

  def oids_in(der)
    collect = ->(node) do
      case node
      when OpenSSL::ASN1::ObjectId then [ node.oid ]
      when OpenSSL::ASN1::Constructive, Array then node.to_a.flat_map(&collect)
      when OpenSSL::ASN1::ASN1Data then node.value.is_a?(Array) ? node.value.flat_map(&collect) : []
      else []
      end
    end
    collect.call(OpenSSL::ASN1.decode(der))
  rescue OpenSSL::ASN1::ASN1Error
    []
  end

  # --- result -----------------------------------------------------------------------------

  def result(format:, cert:, signed_at:, timestamped:, matches_original:)
    check_certificate(cert, signed_at) if cert
    @errors << "integrity" if @checks[:integrity] == false
    @warnings << "original_missing" if @original.nil? && @errors.empty?
    @checks[:trust_chain] = "not_checked"

    subject = cert ? subject_fields(cert.subject) : {}
    issuer = cert ? subject_fields(cert.issuer) : {}

    Result.new(
      status: status_for(matches_original),
      format: format,
      signer_name: [ subject["GN"], subject["SN"] ].compact.join(" ").presence || subject["CN"],
      signer_tax_code: [ subject["serialNumber"], subject["CN"] ].compact.join(" ")[TAX_CODE],
      issuer: issuer["CN"] || issuer["O"],
      certificate_serial: cert&.serial&.to_s(16)&.upcase,
      certificate_valid_until: cert&.not_after,
      signed_at: signed_at,
      timestamped: timestamped,
      qualified: @checks[:qualified] == true && @checks[:qscd] == true,
      matches_original: matches_original,
      details: { "checks" => @checks.stringify_keys, "errors" => @errors.uniq, "warnings" => @warnings.uniq }
    )
  end

  def status_for(matches_original)
    return :invalid if @errors.any?
    return :mismatch if matches_original == false

    :valid_untrusted
  end
end
